from thefuck.utils import replace_argument
from thefuck.specific.git import git_support


@git_support
def match(command):
    has_push = 'push' in command.script
    has_upstream_hint = 'set-upstream' in command.stderr
    return has_push and has_upstream_hint


@git_support
def get_new_command(command):
    lines = command.stderr.split('\n')
    hint_line = lines[-3].strip()
    suggested = hint_line.partition('git ')[2]
    return replace_argument(command.script, 'push', suggested)
